package blockbranch.realistic;
/** The former independent one-block flower sampler is a negative control,along with a regular two-block lattice. */
public final class MeadowFlowerSpacingCheck {
 static boolean flower(int c){return c>=4&&c<=6||c>=11&&c<=13;}
 static boolean legacy(long seed,int x,int z,GroundEcology.Site site){long h=OakBirchWoodland.mix(seed^0x4D4F4E54464C4F57L^x*0x165667B19E3779F9L^z*0xD1B54A32D192ED03L);double strength=GroundEcology.colonyStrength(seed,0x4D4F4E54464C4F52L,x,z,40,9,23,site),vigor=Math.clamp(.7+.35*site.wetness()+.1*site.retention()-.25*site.exposure(),.35,1);return(h>>>11)*0x1.0p-53<(.025+.64*strength)*vigor;}
 static double runs(boolean[]a,int size,int count){double max=0;for(int lag=1;lag<=4;lag++){int n=0;for(int z=12;z<size-12;z++)for(int x=12;x<size-12;x++)for(int[]v:new int[][]{{1,0},{0,1},{1,1},{1,-1}}){boolean all=true;for(int k=0;k<4;k++)all&=a[(z+v[1]*k*lag)*size+x+v[0]*k*lag];if(all)n++;}max=Math.max(max,1000.*n/count);}return max;}
 public static void main(String[]args){for(long seed:new long[]{424242,1,-17}){var d=new DrainageNetwork(new TerrainShape(seed),seed);var c=new ClimateField(seed);var e=new GroundEcology.Field(d::sample,c);var p=blockbranch.realistic.MontaneMeadowFixtures.sceneAnchor(d,seed);int size=256,nb=0,na=0,ng=0;var before=new boolean[size*size];var after=new boolean[size*size];var grid=new boolean[size*size];for(int z=0;z<size;z++)for(int x=0;x<size;x++){int wx=p.x()-size/2+x,wz=p.z()-size/2+z;var site=e.sample(wx,wz);int i=z*size+x;before[i]=legacy(seed,wx,wz,site);after[i]=flower(MontaneMeadow.cover(seed,wx,wz,site,true));grid[i]=Math.floorMod(wx,2)==0&&Math.floorMod(wz,2)==0;if(before[i])nb++;if(after[i])na++;if(grid[i])ng++;if(FlowerMicrosites.accepts(seed,wx,wz))for(int dz=-1;dz<=1;dz++)for(int dx=-1;dx<=1;dx++){if(dx==0&&dz==0||!FlowerMicrosites.accepts(seed,wx+dx,wz+dz))continue;double rr=FlowerMicrosites.radius(FlowerMicrosites.priority(seed,wx,wz))+FlowerMicrosites.radius(FlowerMicrosites.priority(seed,wx+dx,wz+dz)),ax=dx+FlowerMicrosites.offsetX(wx+dx,wz+dz)-FlowerMicrosites.offsetX(wx,wz),az=dz+FlowerMicrosites.offsetZ(wx+dx,wz+dz)-FlowerMicrosites.offsetZ(wx,wz);require(ax*ax+az*az>=rr*rr,"Native-offset stem clearance across negative coordinates/chunk seams");}}
 double oldRate=runs(before,size,nb),newRate=runs(after,size,na),gridRate=runs(grid,size,ng);require(oldRate>150&&gridRate>1000,"Aligned-run diagnostic rejects old dense sampling and regular thinning lattices");require(newRate<80&&newRate<oldRate*.4,"Variable-clearance microsites remove aligned runs at lags1..4");require(na>size*size*.065&&na<size*size*.18,"Flowers retain meaningful restrained coverage");System.out.println("MEADOW_FLOWER_SPACING seed="+seed+" legacyMaxFourRunsPer1000="+oldRate+" corrected="+newRate+" regularLattice="+gridRate+" density="+(na/(double)(size*size)));}
 System.out.println("MEADOW_FLOWER_NATIVE_CLEARANCE_ALIGNED_RUN_NEGATIVE_CONTROL_PASS");}
 static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
}
